235	            }
236	        }
237	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	    }
239	
240	    /**
241	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
242	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
243	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
244	     * blank (e.g. {@code "   "}). The offending field names are reported through an
245	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
246	     * as a 400 response carrying an {@code errors} array of field names.
247	     *
248	     * @param ownerFieldsDto the submitted owner fields
249	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
250	     */
251	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
252	        List<String> blankFields = new ArrayList<>();
253	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
254	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
255	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
256	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
257	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
258	        if (!blankFields.isEmpty()) {
259	            throw new InvalidOwnerFieldsException(blankFields);
260	        }
261	    }
262	
263	    private void addIfBlank(List<String> blankFields, String field, String value) {
264	        if (value != null && value.isBlank()) {
265	            blankFields.add(field);
266	        }
267	    }
268	
269	    /**
270	     * Normalizes an owner's optional email address. When present it is stored and returned
271	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
272	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
273	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
274	     * method runs.
275	     *
276	     * @param email the raw email value from the request, or {@code null} when omitted
277	     * @return the lower-cased email, or {@code null} when none was supplied
278	     */
279	    private String normalizeEmail(String email) {
280	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
281	    }
282	
283	    /**
284	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
285	     * {@code '<LAST3>-<NNNN>'}: {@code LAST3} is the upper-cased first three letters of the
286	     * owner's {@code lastName}, and {@code NNNN} is a global 4-digit zero-padded sequence equal
287	     * to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
288	     *
289	     * @param lastName the last name of the owner being created
290	     * @return the formatted customer code
291	     */
292	    private String nextCustomerCode(String lastName) {
293	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
294	        long sequence = this.clinicService.findAllOwners().size() + 1L;
295	        return String.format("%s-%04d", last3, sequence);
296	    }
297	
298	    /**
299	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
300	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
301	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
302	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
303	     * new owner and surfaced as the read-only {@code namesakeCount} field.
304	     *
305	     * @param firstName the first name of the owner being created
306	     * @param lastName the last name of the owner being created
307	     * @return the number of existing owners with the same first and last name (case-insensitive)
308	     */
309	    private int namesakeCount(String firstName, String lastName) {
310	        return (int) this.clinicService.findAllOwners().stream()
311	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
312	                && equalsIgnoreCase(owner.getLastName(), lastName))
313	            .count();
314	    }
315	
316	    private boolean equalsIgnoreCase(String a, String b) {
317	        return a == null ? b == null : a.equalsIgnoreCase(b);
318	    }
319	
320	    /**
321	     * Rejects a create request whose normalized telephone is already used by any existing owner.
322	     * Existing owners' telephones are reduced to the same canonical form (via
323	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
324	     * only in formatting still collide. A collision is reported through a
325	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
326	     * as a 409 Conflict response.
327	     *
328	     * @param normalizedTelephone the canonical telephone of the owner being created
329	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
330	     */
331	    private void rejectDuplicateTelephone(String normalizedTelephone) {
332	        boolean duplicate = existingOwnerMatches(
333	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
334	            normalizedTelephone);
335	        if (duplicate) {
336	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
337	        }
338	    }
339	
340	    /**
341	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
342	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
343	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
344	     * and the owner being created to the same canonical key and reject a match.
345	     *
346	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
347	     * @param key the canonical key of the owner being created
348	     * @return {@code true} if some existing owner shares the key
349	     */
350	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
351	        return this.clinicService.findAllOwners().stream()
352	            .map(keyExtractor)
353	            .filter(Objects::nonNull)
354	            .anyMatch(key::equals);
355	    }
356	
357	    /**
358	     * Rejects a create request that shares a household with an existing owner: another owner already
359	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
360	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
361	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
362	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
363	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
364	     * check when the request opts in via {@code sharesHousehold}.
365	     *
366	     * @param lastName the last name of the owner being created
367	     * @param address the address of the owner being created
368	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
369	     */
370	    private void rejectDuplicateHousehold(String lastName, String address) {
371	        String canonicalLastName = canonicalizeHousehold(lastName);
372	        String canonicalAddress = canonicalizeHousehold(address);
373	        if (canonicalLastName == null || canonicalAddress == null) {
374	            return;
375	        }
376	        boolean duplicate = this.clinicService.findAllOwners().stream()
377	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
378	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
379	        if (duplicate) {
380	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
381	        }
382	    }
383	
384	    /**
385	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
386	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
387	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
388	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
389	     *
390	     * @param value the raw field value, or {@code null}
391	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
392	     */
393	    private String canonicalizeHousehold(String value) {
394	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
395	    }
396	
397	    /**
398	     * Derives the stable, shared {@code householdId} for an owner joining a household via
399	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
400	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
401	     * owner with the same last name at the same address - regardless of casing or spacing - is
402	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
403	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
404	     *
405	     * @param lastName the last name of the owner being created
406	     * @param address the address of the owner being created
407	     * @return the shared household identifier
408	     */
409	    private String householdId(String lastName, String address) {
410	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
411	        try {
412	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
413	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
414	            StringBuilder sb = new StringBuilder(digest.length * 2);
415	            for (byte b : digest) {
416	                sb.append(String.format("%02X", b));
417	            }
418	            return sb.substring(0, 16);
419	        } catch (java.security.NoSuchAlgorithmException e) {
420	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
421	        }
422	    }
423	}
